RSpec.describe Timekeeping::LocalOwner do
  # "A service bound to another company answers `not_found`."
  # "Every local query filters by `company_id`."
  it "a service bound to another company gets not_found on all five reservation operations, never the stored answer, and writes nothing" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company_a = create(:company)
    company_b = create(:company)
    user_a = create(:user)
    create(:employment, company: company_a, user: user_a)
    user_a.add_role("employee", company_a)
    project_a = create(:project, client: create(:client, company: company_a))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company_a.id, user_id: user_a.id, project_id: project_a.id, work_date: Date.current,
      duration: 60.0, note: "", bill_status: "unbilled", agent_id: 77
    )
    operations = TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
    own_service = Timekeeping::LocalOwner::Actor.service(name: "invoice-boundary", company_id: company_a.id, operations:)
    foreign_service = Timekeeping::LocalOwner::Actor.service(name: "invoice-boundary", company_id: company_b.id, operations:)
    operation_id = SecureRandom.uuid
    call = lambda do |operation, actor, params|
      described_class.call(operation:, company_id: company_a.id, generation:, actor:, params:)
    end
    prepare_params = { "body" => { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active",
                                   "entries" => [entry.id] } }
    commit_params = { "body" => { "invoice_id" => 501, "operation_id" => operation_id } }

    expect(call.call(:prepare, own_service, prepare_params).status).to eq(200)
    stored_commit = call.call(:commit, own_service, commit_params)
    expect(stored_commit.status).to eq(200)

    tables = %w[entries entry_audits entry_outbox_items reservations invoice_operations service_idempotency_receipts]
    snapshot = lambda do
      tables.index_with { |table| ActiveRecord::Base.connection.select_all("SELECT * FROM #{table} ORDER BY 1").to_a }
    end
    before = snapshot.call

    requests = {
      prepare: prepare_params,
      commit: commit_params,
      abort: commit_params,
      mark_billed: { "invoice_id" => 501, "body" => { "operation_id" => SecureRandom.uuid } },
      detach_entries: { "agent_id" => 77, "body" => { "operation_id" => SecureRandom.uuid } }
    }
    answers = requests.to_h { |operation, params| [operation, call.call(operation, foreign_service, params)] }

    expect(answers.transform_values { |outcome| [outcome.status, outcome.body] })
      .to eq(requests.keys.index_with { [404, { "reason" => "not_found" }] })
    expect(snapshot.call).to eq(before)
  end
end

RSpec.describe Timekeeping::LocalOwner do
  # "Every local query filters by `company_id`."
  # contracts/timekeeping/reservations.yml rules.company_mismatch: "An entry outside the path company is a not_found conflict"
  it "a prepare naming another company's entry gets the same not_found conflict as a missing id and reserves nothing" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company_a = create(:company)
    company_b = create(:company)
    make_entry = lambda do |company|
      user = create(:user)
      create(:employment, company:, user:)
      user.add_role("employee", company)
      project = create(:project, client: create(:client, company:))
      Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                      work_date: Date.current, duration: 60.0, note: "", bill_status: "unbilled")
    end
    own_entry = make_entry.call(company_a)
    foreign_entry = make_entry.call(company_b)
    missing_id = Timekeeping::LocalEntry.maximum(:id) + 1000
    service = Timekeeping::LocalOwner::Actor.service(
      name: "invoice-boundary", company_id: company_a.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
    )
    versions_before = Timekeeping::LocalEntry.where(id: [own_entry.id, foreign_entry.id]).order(:id).pluck(:id, :version)
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    counts_before = %w[reservations invoice_operations entry_outbox_items entry_audits].index_with { |table| count.call(table) }

    outcome = described_class.call(
      operation: :prepare, company_id: company_a.id, generation:, actor: service,
      params: { "body" => { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active",
                            "entries" => [own_entry.id, foreign_entry.id, missing_id] } }
    )

    expect(outcome.status).to eq(409)
    expect(outcome.body).to eq(
      "reason" => "conflict",
      "conflicts" => [{ "entry_id" => foreign_entry.id, "reason" => "not_found" },
                      { "entry_id" => missing_id, "reason" => "not_found" }]
    )
    expect(Timekeeping::LocalEntry.where(id: [own_entry.id, foreign_entry.id]).order(:id).pluck(:id, :version))
      .to eq(versions_before)
    expect(%w[reservations invoice_operations entry_outbox_items entry_audits].index_with { |table| count.call(table) })
      .to eq(counts_before)
  end
end

RSpec.describe Timekeeping::LocalOwner do
  # "mark_billed bills only the entries the invoice holds by committed reservation. detach_entries clears one agent on the caller company's entries only."
  # "Every local query filters by `company_id`."
  it "mark_billed and detach_entries change only the caller company's entries when another company shares the invoice and agent ids" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company_a = create(:company)
    company_b = create(:company)
    make_entry = lambda do |company|
      user = create(:user)
      create(:employment, company:, user:)
      user.add_role("employee", company)
      project = create(:project, client: create(:client, company:))
      Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                      work_date: Date.current, duration: 60.0, note: "", bill_status: "unbilled",
                                      agent_id: 77)
    end
    own_entry = make_entry.call(company_a)
    foreign_entry = make_entry.call(company_b)
    # The other company's invoice 501 holds its entry by committed reservation.
    ApplicationRecord.connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, company_b.id, foreign_entry.id, SecureRandom.uuid]))
      INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
      VALUES (?, ?, 501, ?, 'committed', 'active', NOW())
    SQL
    foreign_before = foreign_entry.reload.attributes
    service = Timekeeping::LocalOwner::Actor.service(
      name: "invoice-boundary", company_id: company_a.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
    )
    command = lambda do |operation, params|
      described_class.call(operation:, company_id: company_a.id, generation:, actor: service,
                           params: params.merge("body" => { "operation_id" => SecureRandom.uuid }))
    end

    billed = command.call(:mark_billed, "invoice_id" => 501)
    detached = command.call(:detach_entries, "agent_id" => 77)

    expect([billed.status, billed.body]).to eq([200, { "billed" => 0 }])
    expect([detached.status, detached.body]).to eq([200, { "detached" => 1 }])
    expect(own_entry.reload.agent_id).to be_nil
    expect(foreign_entry.reload.attributes).to eq(foreign_before)
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company_b.id).count).to eq(0)
    expect(ActiveRecord::Base.connection.select_value(
      ApplicationRecord.sanitize_sql_array(["SELECT COUNT(*) FROM entry_audits WHERE company_id = ?", company_b.id])
    ).to_i).to eq(0)
  end
end

RSpec.describe Timekeeping::LocalOwner do
  # "The same operation_id from two services, or from two companies, gives separate receipts"
  it "the same operation_id from two companies' services gives separate operations and receipts, and one company's abort leaves the other's reservation" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    operation_id = SecureRandom.uuid
    setups = [create(:company), create(:company)].map do |company|
      user = create(:user)
      create(:employment, company:, user:)
      user.add_role("employee", company)
      project = create(:project, client: create(:client, company:))
      entry = Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                              work_date: Date.current, duration: 60.0, note: "", bill_status: "unbilled")
      service = Timekeeping::LocalOwner::Actor.service(
        name: "invoice-boundary", company_id: company.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
      )
      { company:, entry:, service: }
    end
    call = lambda do |setup, operation, body|
      described_class.call(operation:, company_id: setup[:company].id, generation:, actor: setup[:service],
                           params: { "body" => body })
    end
    first, second = setups

    prepared = setups.map do |setup|
      call.call(setup, :prepare, "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active",
                                 "entries" => [setup[:entry].id])
    end
    aborted = call.call(first, :abort, "invoice_id" => 501, "operation_id" => operation_id)
    committed = call.call(second, :commit, "invoice_id" => 501, "operation_id" => operation_id)

    expect(prepared.map(&:status)).to eq([200, 200])
    expect(prepared.map { |outcome| outcome.body.fetch("entries") }).to eq(
      setups.map { |setup| [{ "entry_id" => setup[:entry].id, "company_id" => setup[:company].id }] }
    )
    expect([aborted.status, aborted.body]).to eq([200, { "dropped" => 1 }])
    expect([committed.status, committed.body]).to eq([200, { "reserved" => 1, "released" => 0 }])
    reservations = ApplicationRecord.connection.select_rows(<<~SQL.squish)
      SELECT company_id, entry_id, state FROM reservations ORDER BY company_id
    SQL
    expect(reservations).to eq([[second[:company].id, second[:entry].id, "committed"]])
    receipts = ApplicationRecord.connection.select_rows(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, operation_id]))
      SELECT company_id, operation FROM service_idempotency_receipts WHERE key = ? ORDER BY company_id
    SQL
    expect(receipts).to eq([[first[:company].id, "abort"], [second[:company].id, "commit"]])
    expect(ApplicationRecord.connection.select_value(ApplicationRecord.sanitize_sql_array(
      ["SELECT COUNT(*) FROM invoice_operations WHERE operation_id = ?", operation_id]
    )).to_i).to eq(2)
  end
end
